                     'NA', '#NA', 'NULL', 'NaN', 'nan', ''])
    if na_values is None:
        na_values = NA_VALUES
    else:
        na_values = set(list(na_values))

    def _convert_float(val):
        if val in na_values:
            return np.nan
        else:
            try:
