def _remove_html_comments(body):
    start = body.find(b"<!--")
    while start != -1:
        end = body.find(b"-->", start + 1)
        if end == -1:
            return body[:start]
        else:
            body = body[:start] + body[end + 3 :]
            start = body.find(b"<!--")
    return body


