class _ReplicateState(_State):
    def __init__(self, ignored_modules: Optional[Iterable[torch.nn.Module]] = None) -> None:
        self.module: Optional[nn.Module] = None
        self.has_initialized: bool = False
        self._param_list: nn.ParameterList = nn.ParameterList()
        self.kwargs: dict = {}
        self.ignored_modules: Set[torch.nn.Module] = set(ignored_modules) if ignored_modules is not None else set()

    @contract()
    def replicate(self, module: nn.Module, ignored_modules: Optional[Iterable[torch.nn.Module]] = None, **kwargs) -> nn.Module:
        r"""Replicates a module

        Args:
            module (torch.nn.Module): module to replicate

        Example::
            >>> # xdoctest: +REQUIRES(module:torch._C._distributed_c10d)
            >>> module = nn.Linear(3, 3)
            >>> replicate(module)
        """
        torch._C._log_api_usage_once("torch.distributed.replicate")
        if "device_id" in kwargs:
            if not isinstance(kwargs["device_id"], (int, torch.device)):
                raise RuntimeError(
                    f"Expected device_id to be int or torch.device, but got {type(kwargs['device_id'])}"
                )
        self.mark_module(module, ignored_modules=ignored_modules, **kwargs)
        return module

    def _is_fully_sharded(self, module: nn.Module) -> bool:
        r"""Check if module is marked with fully_shard."""
        return "fully_shard" in _get_registry(module)

