    gm1 = cnts.graphs[1]
    # Check that the first graph does not have sigmoid. sigmoid is used in
    # both hook and disabled module.
    self.assertTrue(
        all(node.target is not torch.sigmoid for node in gm1.graph.nodes)
    )

