def test_dict_subclass_contains(self):
    # pattern from huggingface
    class ClassInstantier(collections.OrderedDict):
        pass

    @torch.compile(fullgraph=True, backend="eager")
    def f(x, d):
        if "key1" in d:
            x = x + 2
        if "key2" in d:
            x = x + 4
        x = x + 8
        return x

