                constants_offset += 1
            else:
                args_full.append(args[proxies_offset])
                proxies_offset += 1

        kwargs_full = {}
        kwargs_full.update(kwargs)
        kwargs_full.update(constant_kwargs)
        return inner_fn(*args_full, **kwargs_full)

    def subclass_fn_call(*args, **kwargs):
