            self.layer0 = SimpleLinear()
            self.layer1 = torch.nn.Linear(4, 4)

        def forward(self, inp):
            z = self.layer0(torch.sin(inp))
            return self.layer1(z)

    def hook(module, args):
        inp = args[0].sigmoid()
        return (inp,)

    model = SimpleModel()
    model.layer0.register_forward_pre_hook(hook)

