def _communicate_with_select(self, input, endtime, orig_timeout):
    if not self._communication_started:
        self._read_set = []
        self._write_set = []
        if self.stdin and input:
            self._write_set.append(self.stdin)
        if self.stdout:
            self._read_set.append(self.stdout)
        if self.stderr:
            self._read_set.append(self.stderr)

    self._save_input(input)

    stdout = None  # Return
    stderr = None  # Return

    if self.stdout:
        if not self._communication_started:
            self._stdout_buff = []
        stdout = self._stdout_buff
    if self.stderr:
        if not self._communication_started:
            self._stderr_buff = []
        stderr = self._stderr_buff

    while self._read_set or self._write_set:
        timeout = self._remaining_time(endtime)
        if timeout is not None and timeout < 0:
            raise TimeoutExpired(self.args, orig_timeout)
        try:
            (rlist, wlist, xlist) = select.select(self._read_set, self._write_set, [], timeout)
        except select.error as e:
            if e.args[0] == errno.EINTR:
                continue
            raise

        # According to the docs, returning three empty lists indicates
        # that the timeout expired.
        if not (rlist or wlist or xlist):
            raise TimeoutExpired(self.args, orig_timeout)
        # We also check what time it is ourselves for good measure.
        self._check_timeout(endtime, orig_timeout)

        # XXX Rewrite these to use non-blocking I/O on the
        # file objects; they are no longer using C stdio!

        if self.stdin in wlist:
            chunk = self._input[self._input_offset : self._input_offset + _PIPE_BUF]
            try:
                bytes_written = os.write(self.stdin.fileno(), chunk)
            except OSError as e:
                if e.errno == errno.EPIPE:
                    self.stdin.close()
                    self._write_set.remove(self.stdin)
                else:
                    raise
            else:
                self._input_offset += bytes_written
                if self._input_offset >= len(self._input):
                    self.stdin.close()
                    self._write_set.remove(self.stdin)

        if self.stdout in rlist:
            data = os.read(self.stdout.fileno(), 1024)
            if not data:
                self.stdout.close()
                self._read_set.remove(self.stdout)
            stdout.append(data)

        if self.stderr in rlist:
            data = os.read(self.stderr.fileno(), 1024)
            if not data:
                self.stderr.close()
                self._read_set.remove(self.stderr)
            stderr.append(data)

    return (stdout, stderr)

